"use client";
import { useEffect, useRef, useState } from "react";
import { Alert, AlertAction, AlertTitle } from "@ui/alert";
import { Button } from "@ui/button";
import { DropdownContent, DropdownMenu, DropdownTrigger } from "@ui/dropdown";
import { Empty, EmptyHeader, EmptyTitle, EmptyDescription } from "@ui/empty";
import { InlineNotice, InlineNoticeContent } from "@ui/inline-notice";
import { MenuItem } from "@ui/menu-item";
import { Tabs, TabsList, TabItem, TabPanel } from "@ui/tabs";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { resolveArtifactLabels } from "./artifact-panel/labels";
import { ArtifactTabs } from "./artifact-panel/tabs";
import { ArtifactPreview, ArtifactPreviewBoundary } from "./artifact-panel/preview";
import { artifactReviewStatus, artifactText, artifactVersionKey, artifactViews, downloadArtifact, getPendingReviewResources, safeArtifactUrl } from "./artifact-panel/utils";
import type { ArtifactLabels, ArtifactPanelProps, ArtifactResource, ArtifactReviewDecision, ArtifactView } from "./artifact-panel/types";
function ArtifactSurface({ resource, labels, onReference, onRetry, renderPreview }: {
    resource: ArtifactResource;
    labels: ArtifactLabels;
} & Pick<ArtifactPanelProps, "onReference" | "onRetry" | "renderPreview">) {
    const views = artifactViews(resource);
    const [selectedView, setView] = useState<ArtifactView>(views[0]);
    const view = views.includes(selectedView) ? selectedView : views[0];
    const [split, setSplit] = useState(false);
    const [notice, setNotice] = useState("");
    const [actionBusy, setActionBusy] = useState(false);
    const actionLock = useRef(false);
    const Link = useIcon("link");
    const Copy = useIcon("copy");
    const text = artifactText(resource);
    const reviewStatus = artifactReviewStatus(resource);
    const url = "url" in resource ? safeArtifactUrl(resource.url, resource.kind === "url") : undefined;
    const downloadable = resource.kind !== "url" && ("content" in resource || url || safeArtifactUrl(resource.downloadUrl));
    const run = async (action: () => void | Promise<void>, success: string, failed: string) => {
        if (actionLock.current)
            return;
        actionLock.current = true;
        setActionBusy(true);
        setNotice("");
        try {
            await action();
            setNotice(success);
        }
        catch {
            setNotice(failed);
        }
        finally {
            actionLock.current = false;
            setActionBusy(false);
        }
    };
    return <>
    <div className="flex shrink-0 flex-wrap items-center gap-2 border-b-hairline border-border px-4 py-2">
      <span className="min-w-0 flex-1 truncate font-mono text-label text-fg-muted" title={resource.path ?? resource.name}>{resource.path ?? resource.name}</span>
      {reviewStatus && <span className="shrink-0 text-label text-fg-muted">{labels[reviewStatus]}</span>}
      <div className="flex flex-wrap items-center gap-1">
        {text !== undefined && <Button size="xs" variant="ghost" leadingIcon={Copy} disabled={actionBusy} onClick={() => void run(() => navigator.clipboard.writeText(text), labels.copied, labels.copyFailed)}>{labels.copy}</Button>}
        {downloadable && <Button size="xs" variant="ghost" onClick={() => downloadArtifact(resource)}>{labels.download}</Button>}
        {url && <Button size="xs" variant="ghost" asChild><a href={url} target="_blank" rel="noopener noreferrer">{labels.openExternal}</a></Button>}
        {onReference && <Button size="xs" variant="ghost" leadingIcon={Link} disabled={actionBusy} onClick={() => void run(() => onReference(resource), labels.referenced, labels.referenceFailed)}>{labels.reference}</Button>}
      </div>
    </div>
    {(views.length > 1 || view === "diff") && <div className="flex shrink-0 flex-wrap items-center justify-between gap-2 border-b-hairline border-border px-4 py-2">
      <Tabs value={view} onValueChange={(value) => setView(value as ArtifactView)} variant="segment" color="neutral">
        <TabsList aria-label={resource.name}>{views.map((item) => <TabItem key={item} value={item} label={labels[item]}/>)}</TabsList>
      </Tabs>
      {view === "diff" && <Button variant="ghost" size="xs" aria-pressed={split} onClick={() => setSplit(!split)}>{split ? labels.split : labels.unified}</Button>}
    </div>}
    {notice && <div className="px-4 py-2 text-label text-fg-muted" role="status">{notice}</div>}
    <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-auto" data-slot="artifact-viewport" tabIndex={0} aria-label={`${labels.preview}: ${resource.name}`}>
      <ArtifactPreviewBoundary key={`${view}:${split}:${resource.status ?? "ready"}`} labels={labels}>
        <ArtifactPreview resource={resource} view={view} split={split} labels={labels} renderPreview={renderPreview} onRetry={onRetry ? () => void run(() => onRetry(resource), "", labels.failed) : undefined}/>
      </ArtifactPreviewBoundary>
    </div>
  </>;
}
function ArtifactTabPanel({ resource, active, ...props }: {
    resource: ArtifactResource;
    active: boolean;
    labels: ArtifactLabels;
} & Pick<ArtifactPanelProps, "onReference" | "onRetry" | "renderPreview">) {
    const [visited, setVisited] = useState(active);
    useEffect(() => { if (active)
        setVisited(true); }, [active]);
    return <TabPanel value={resource.id} keepMounted className={cn("min-h-0 min-w-0 flex-1 flex-col", active ? "flex" : "hidden")}>
    {(active || visited) && <ArtifactSurface resource={resource} {...props}/>}
  </TabPanel>;
}
export function ArtifactPanel({ resources, activeId, defaultActiveId, onActiveIdChange, onClose, onCloseMany, addAction, onReview, onReference, onRetry, renderPreview, labels: overrides, locale, className, ...props }: ArtifactPanelProps) {
    const labels = resolveArtifactLabels(locale, overrides);
    const [selectedId, setSelectedId] = useState(defaultActiveId ?? resources[0]?.id);
    const requested = activeId === undefined ? selectedId : activeId;
    const active = resources.find((resource) => resource.id === requested) ?? resources[0];
    const [reviewing, setReviewing] = useState(false);
    const [reviewErrors, setReviewErrors] = useState<string[]>([]);
    const reviewLock = useRef(false);
    const root = useRef<HTMLElement>(null);
    const resolvedId = active?.id;
    const Previous = useIcon("chevron-left");
    const Next = useIcon("chevron-right");
    const Down = useIcon("chevron-down");
    const More = useIcon("ellipsis");
    const Check = useIcon("check");
    useEffect(() => {
        if (activeId === undefined)
            setSelectedId(resolvedId);
    }, [activeId, resolvedId]);
    const select = (id: string) => {
        if (activeId === undefined)
            setSelectedId(id);
        onActiveIdChange?.(id);
    };
    const focusTab = (id?: string) => requestAnimationFrame(() => {
        const tab = Array.from(root.current?.querySelectorAll<HTMLElement>("[data-artifact-id]") ?? []).find((node) => node.dataset.artifactId === id);
        if (tab)
            tab.focus();
        else
            root.current?.querySelector<HTMLElement>("button")?.focus();
    });
    const closable = !!(onClose || onCloseMany);
    const close = (items: readonly ArtifactResource[]) => {
        if (!closable || !items.length)
            return;
        const ids = new Set(items.map((item) => item.id));
        const index = resources.findIndex((item) => item.id === active?.id);
        const next = active && !ids.has(active.id) ? active
            : resources.slice(index + 1).find((item) => !ids.has(item.id)) ?? resources.slice(0, index).reverse().find((item) => !ids.has(item.id));
        if (onCloseMany)
            onCloseMany(items);
        else
            items.forEach((item) => onClose?.(item));
        if (next && next.id !== active?.id)
            select(next.id);
        focusTab(next?.id);
    };
    const pending = getPendingReviewResources(resources);
    const pendingIndex = pending.findIndex((resource) => resource.id === active?.id);
    const currentPending = pending[pendingIndex];
    const failed = pending.filter((resource) => reviewErrors.includes(artifactVersionKey(resource)));
    const navigatePending = (direction: -1 | 1) => {
        if (!pending.length)
            return;
        const index = pendingIndex < 0 ? (direction === 1 ? 0 : pending.length - 1) : (pendingIndex + direction + pending.length) % pending.length;
        select(pending[index].id);
    };
    const review = async (items: readonly ArtifactResource[], decision: ArtifactReviewDecision) => {
        if (!onReview || reviewLock.current || !items.length)
            return;
        reviewLock.current = true;
        setReviewing(true);
        const itemKeys = new Set(items.map(artifactVersionKey));
        const pendingKeys = new Set(pending.map(artifactVersionKey));
        setReviewErrors((current) => current.filter((key) => pendingKeys.has(key) && !itemKeys.has(key)));
        try {
            const results = await Promise.allSettled(items.map((resource) => Promise.resolve().then(() => onReview(resource, decision))));
            const errors = items.filter((_, index) => results[index].status === "rejected").map(artifactVersionKey);
            setReviewErrors((current) => [...current, ...errors]);
        }
        finally {
            reviewLock.current = false;
            setReviewing(false);
        }
    };
    return <section {...props} ref={root} aria-label={props["aria-label"] ?? labels.panel} data-slot="artifact-panel" className={cn("flex size-full min-h-0 min-w-0 flex-col overflow-hidden bg-surface-floating text-fg-default", className)}>
    {active ? <Tabs value={active.id} onValueChange={select} variant="segment" color="default" className="flex min-h-0 flex-1 flex-col">
      <ArtifactTabs resources={resources} activeId={active.id} labels={labels} onSelect={select} onClose={closable ? (resource) => close([resource]) : undefined} onCloseOthers={() => close(resources.filter((resource) => resource.id !== active.id))} onCloseAll={() => close(resources)} addAction={addAction}/>
      {resources.map((resource) => <ArtifactTabPanel key={artifactVersionKey(resource)} resource={resource} active={resource.id === active.id} labels={labels} onReference={onReference} onRetry={onRetry} renderPreview={renderPreview}/>)}
    </Tabs> : <>
      {addAction && <div className="flex shrink-0 items-center border-b-hairline border-border bg-surface-floating p-2">{addAction}</div>}
      <div className="flex flex-1 items-center justify-center p-6"><Empty reason="first-use" scope="inline" density="compact"><EmptyHeader><EmptyTitle>{labels.empty}</EmptyTitle><EmptyDescription>{labels.emptyDescription}</EmptyDescription></EmptyHeader></Empty></div>
    </>}
    {onReview && pending.length > 0 && <div data-slot="artifact-review-bar" className="shrink-0 p-3">
      <Alert status="info" role="group" aria-busy={reviewing} className="flex flex-wrap justify-between gap-2">
        <AlertTitle>
          <DropdownMenu>
            <DropdownTrigger render={<Button variant="ghost" trailingIcon={Down} aria-label={labels.reviewList}><span role="status">{reviewing ? labels.reviewing : labels.remaining(pending.length)}</span></Button>}/>
            <DropdownContent align="start" aria-label={labels.reviewList} checkedIndex={pendingIndex < 0 ? undefined : pendingIndex}>
              {pending.map((resource, index) => <MenuItem key={artifactVersionKey(resource)} index={index} label={resource.name} title={resource.path ?? resource.name} checked={resource.id === active?.id} trailing={failed.includes(resource) ? <span className="text-label text-fg-danger">{labels.failed}</span> : undefined} onSelect={() => { select(resource.id); focusTab(resource.id); }}/>)}
            </DropdownContent>
          </DropdownMenu>
        </AlertTitle>
        <AlertAction className="mt-0 flex-wrap">
          <Button variant="tertiary" iconOnly aria-label={labels.previousPending} disabled={pending.length < 2 && !!currentPending} onClick={() => navigatePending(-1)}><Previous aria-hidden/></Button>
          <Button variant="tertiary" iconOnly aria-label={labels.nextPending} disabled={pending.length < 2 && !!currentPending} onClick={() => navigatePending(1)}><Next aria-hidden/></Button>
          {currentPending ? <>
            <Button variant="ghost" disabled={reviewing} onClick={() => void review([currentPending], "reject")}>{labels.reject}</Button>
            <Button variant="neutral" leadingIcon={Check} disabled={reviewing} onClick={() => void review([currentPending], "accept")}>{labels.accept}</Button>
          </> : <Button variant="neutral" onClick={() => navigatePending(1)}>{labels.startReview}</Button>}
          <DropdownMenu>
            <DropdownTrigger render={<Button variant="tertiary" iconOnly aria-label={labels.reviewActions} disabled={reviewing}><More aria-hidden/></Button>}/>
            <DropdownContent align="end">
              <MenuItem index={0} label={labels.rejectAll} disabled={reviewing} onSelect={() => void review(pending, "reject")}/>
              <MenuItem index={1} label={labels.acceptAll} disabled={reviewing} onSelect={() => void review(pending, "accept")}/>
            </DropdownContent>
          </DropdownMenu>
        </AlertAction>
      </Alert>
    </div>}
    {failed.length > 0 && <div className="shrink-0 px-3 pb-3"><InlineNotice variant="emphasized" tone="danger" role="alert"><InlineNoticeContent className="break-words">{labels.reviewFailed} {failed.map((resource) => resource.name).join(", ")}</InlineNoticeContent></InlineNotice></div>}
  </section>;
}
export { artifactEnLabels, artifactZhLabels } from "./artifact-panel/labels";
export { getPendingReviewResources } from "./artifact-panel/utils";
export type { ArtifactReviewStatus, ArtifactReviewDecision, ArtifactView, ArtifactResource, ArtifactLabels, ArtifactPanelProps } from "./artifact-panel/types";

import type { HTMLAttributes, ReactNode } from "react";
export type ArtifactReviewStatus = "pending" | "accepted" | "rejected";
export type ArtifactReviewDecision = "accept" | "reject";
export type ArtifactView = "preview" | "source" | "diff";
interface ArtifactBase {
    /** Unique within a panel. Preserve this ID across content revisions. */
    id: string;
    /** Change when content changes; review decisions belong to this version. */
    version: string;
    name: string;
    path?: string;
    messageId?: string;
    status?: "ready" | "loading" | "error";
    error?: string;
    downloadUrl?: string;
    /** File size in bytes. Text resources fall back to their UTF-8 content size. */
    size?: number;
}
export type ArtifactResource = ArtifactBase & ({
    kind: "code";
    content: string;
    previousContent?: string;
    previousPath?: string;
    review?: ArtifactReviewStatus;
} | {
    kind: "markdown";
    content: string;
    previousContent?: string;
    review?: ArtifactReviewStatus;
} | {
    kind: "text";
    content: string;
} | {
    kind: "image";
    url: string;
    alt?: string;
} | {
    kind: "url";
    url: string;
} | {
    kind: "file";
    url?: string;
    mimeType?: string;
});
export interface ArtifactLabels {
    panel: string;
    resources: string;
    more: string;
    empty: string;
    emptyDescription: string;
    preview: string;
    source: string;
    diff: string;
    unified: string;
    split: string;
    copy: string;
    copied: string;
    copyFailed: string;
    download: string;
    reference: string;
    referenced: string;
    referenceFailed: string;
    openExternal: string;
    refresh: string;
    close: (name: string) => string;
    closeOthers: string;
    closeAll: string;
    loading: string;
    failed: string;
    retry: string;
    unsupported: string;
    unavailableUrl: string;
    webNotice: string;
    zoomIn: string;
    zoomOut: string;
    fit: string;
    actualSize: string;
    panImage: string;
    accept: string;
    reject: string;
    acceptAll: string;
    rejectAll: string;
    pending: string;
    accepted: string;
    rejected: string;
    reviewing: string;
    reviewFailed: string;
    reviewActions: string;
    reviewList: string;
    previousPending: string;
    nextPending: string;
    startReview: string;
    remaining: (count: number) => string;
    workspace: string;
    conversation: string;
    showPanel: string;
    hidePanel: string;
    resize: string;
}
export interface ArtifactPanelProps extends Omit<HTMLAttributes<HTMLElement>, "children" | "onSelect"> {
    /** The open resources, in tab order. The host owns closing and persistence. */
    resources: readonly ArtifactResource[];
    activeId?: string | null;
    defaultActiveId?: string;
    onActiveIdChange?: (id: string) => void;
    onClose?: (resource: ArtifactResource) => void;
    /** Handles every close operation atomically when supplied; otherwise calls onClose for each resource. */
    onCloseMany?: (resources: readonly ArtifactResource[]) => void;
    /** Optional action beside the content tabs, such as a plus-button resource picker. */
    addAction?: ReactNode;
    /** Resolve after committing this exact resource version; reject on failure. */
    onReview?: (resource: ArtifactResource, decision: ArtifactReviewDecision) => void | Promise<void>;
    onReference?: (resource: ArtifactResource) => void | Promise<void>;
    onRetry?: (resource: ArtifactResource) => void | Promise<void>;
    /** Return undefined to use the built-in viewer. */
    renderPreview?: (resource: ArtifactResource) => ReactNode | undefined;
    labels?: Partial<ArtifactLabels>;
    locale?: string;
}

import type { ArtifactResource, ArtifactView } from "./types";
export function artifactVersionKey(resource: ArtifactResource) {
    return JSON.stringify([resource.id, resource.version]);
}
export function artifactViews(resource: ArtifactResource): ArtifactView[] {
    if (resource.kind === "code")
        return resource.previousContent !== undefined ? ["diff", "source"] : ["source"];
    if (resource.kind === "markdown")
        return resource.previousContent !== undefined ? ["preview", "source", "diff"] : ["preview", "source"];
    return resource.kind === "text" ? ["source"] : ["preview"];
}
export function artifactIsReviewable(resource: ArtifactResource) {
    return (resource.kind === "code" || resource.kind === "markdown") && resource.previousContent !== undefined && resource.review !== undefined;
}
export function artifactReviewStatus(resource: ArtifactResource) {
    return artifactIsReviewable(resource) && "review" in resource ? resource.review : undefined;
}
/** Ready revisions awaiting a decision, preserving the host's resource order. */
export function getPendingReviewResources(resources: readonly ArtifactResource[]) {
    return resources.filter((resource) => artifactReviewStatus(resource) === "pending" && (!resource.status || resource.status === "ready"));
}
/** Web frames only receive HTTP(S). File/image URLs may also be local blob URLs. */
export function safeArtifactUrl(url?: string, web = false): string | undefined {
    if (!url?.trim())
        return undefined;
    try {
        const parsed = new URL(url, "https://preview.invalid");
        return (web ? ["http:", "https:"] : ["http:", "https:", "blob:"]).includes(parsed.protocol) ? url : undefined;
    }
    catch {
        return undefined;
    }
}
export function artifactText(resource: ArtifactResource) {
    return "content" in resource ? resource.content : "url" in resource ? safeArtifactUrl(resource.url, resource.kind === "url") : undefined;
}
export function artifactSizeText(resource: ArtifactResource, locale = "en") {
    const bytes = resource.size !== undefined && Number.isFinite(resource.size) && resource.size >= 0
        ? resource.size : "content" in resource ? new TextEncoder().encode(resource.content).byteLength : undefined;
    if (bytes === undefined)
        return undefined;
    const units = ["B", "KB", "MB", "GB", "TB"];
    const unit = bytes > 0 ? Math.max(0, Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1)) : 0;
    return `${new Intl.NumberFormat(locale, { maximumFractionDigits: unit ? 1 : 0 }).format(bytes / 1024 ** unit)} ${units[unit]}`;
}
export function downloadArtifact(resource: ArtifactResource) {
    const remote = safeArtifactUrl(resource.downloadUrl) ?? ("url" in resource ? safeArtifactUrl(resource.url, resource.kind === "url") : undefined);
    const blob = !remote && "content" in resource ? URL.createObjectURL(new Blob([resource.content], { type: "text/plain;charset=utf-8" })) : undefined;
    const url = remote ?? blob;
    if (!url)
        return;
    const link = document.createElement("a");
    link.href = url;
    link.download = resource.name;
    link.rel = "noopener noreferrer";
    link.target = "_blank";
    link.click();
    if (blob)
        setTimeout(() => URL.revokeObjectURL(blob), 1000);
}

"use client";
import { useLayoutEffect, useRef, useState } from "react";
import { Button } from "@ui/button";
import { DropdownContent, DropdownMenu, DropdownSeparator, DropdownTrigger } from "@ui/dropdown";
import { FileType } from "@ui/file-type";
import { MenuItem } from "@ui/menu-item";
import { TabItem, Tabs, TabsList } from "@ui/tabs";
import { useIcon } from "@lib/icon-context";
import type { ArtifactLabels, ArtifactPanelProps, ArtifactResource } from "./types";
/** Keep the selected resource visible and fit complete tabs in their original order. */
export function visibleArtifactIds(resources: readonly ArtifactResource[], activeId: string, widths: readonly number[], available: number, moreWidth: number, gap: number): Set<string> {
    if (!resources.length)
        return new Set();
    // Unknown measurements retain SSR markup; a measured zero budget still needs overflow handling.
    if (widths.length !== resources.length || widths.some((width) => width <= 0))
        return new Set(resources.map((resource) => resource.id));
    if (widths.reduce((sum, width) => sum + width, 0) + Math.max(0, resources.length - 1) * gap <= available)
        return new Set(resources.map((resource) => resource.id));
    const activeIndex = Math.max(0, resources.findIndex((resource) => resource.id === activeId));
    const visible = new Set([resources[activeIndex].id]);
    let used = widths[activeIndex];
    const budget = available - moreWidth;
    resources.forEach((resource, index) => {
        if (index !== activeIndex && used + gap + widths[index] <= budget) {
            visible.add(resource.id);
            used += gap + widths[index];
        }
    });
    return visible;
}
export function ArtifactTabs({ resources, activeId, labels, onSelect, onClose, onCloseOthers, onCloseAll, addAction }: {
    resources: readonly ArtifactResource[];
    activeId: string;
    labels: ArtifactLabels;
    onSelect: (id: string) => void;
    onCloseOthers?: () => void;
    onCloseAll?: () => void;
} & Pick<ArtifactPanelProps, "onClose" | "addAction">) {
    const availableRef = useRef<HTMLDivElement>(null);
    const measureRef = useRef<HTMLDivElement>(null);
    const moreRef = useRef<HTMLDivElement>(null);
    const [layout, setLayout] = useState({ available: 0, widths: [] as number[], moreWidth: 0, gap: 0 });
    const Globe = useIcon("globe");
    const More = useIcon("ellipsis");
    const closable = !!onClose;
    // Content and review updates do not change tab geometry (for example while a reply streams).
    const measurementKey = JSON.stringify(resources.map(({ id, name, kind }) => [id, name, kind]));
    useLayoutEffect(() => {
        const available = availableRef.current;
        const measurement = measureRef.current;
        const more = moreRef.current;
        if (!available || !measurement || !more)
            return;
        const measure = () => {
            const widths = Array.from(measurement.querySelectorAll<HTMLElement>("[data-measure-artifact]")).map((tab) => (tab.closest<HTMLElement>('[data-slot="closable-tab"]') ?? tab).getBoundingClientRect().width);
            const gap = parseFloat(getComputedStyle(measurement).columnGap) || 0;
            const actionGap = parseFloat(getComputedStyle(available).columnGap) || 0;
            const next = { available: available.clientWidth, widths, gap, moreWidth: more.getBoundingClientRect().width + actionGap };
            setLayout((current) => current.available === next.available && current.moreWidth === next.moreWidth && current.gap === gap && current.widths.length === widths.length && current.widths.every((width, index) => width === widths[index]) ? current : next);
        };
        measure();
        if (typeof ResizeObserver === "undefined")
            return;
        const observer = new ResizeObserver(measure);
        observer.observe(available);
        observer.observe(measurement);
        observer.observe(more);
        return () => observer.disconnect();
    }, [measurementKey, activeId, closable]);
    // Closing actions keep the menu present even when every tab fits.
    const visible = visibleArtifactIds(resources, activeId, layout.widths, layout.available - (closable ? layout.moreWidth : 0), closable ? 0 : layout.moreWidth, layout.gap);
    const leading = (resource: ArtifactResource) => resource.kind === "url" ? <Globe size={16} aria-hidden/> : <FileType fileName={resource.name} variant="mono" size="mini" aria-hidden/>;
    const focusSelected = (id: string) => requestAnimationFrame(() => {
        Array.from(availableRef.current?.querySelectorAll<HTMLElement>("[data-artifact-id]") ?? []).find((tab) => tab.dataset.artifactId === id)?.focus();
    });
    return <div data-slot="artifact-tab-bar" className="relative flex shrink-0 items-center gap-2 border-b-hairline border-border bg-surface-floating p-2">
    <div ref={availableRef} className="flex min-w-0 flex-1 items-center gap-2">
      <div className="min-w-0 flex-1">
        <TabsList aria-label={labels.resources}>
          {resources.filter((resource) => visible.has(resource.id)).map((resource) => <TabItem key={resource.id} value={resource.id} label={resource.name} title={resource.name} data-artifact-id={resource.id} leading={leading(resource)} closeLabel={labels.close(resource.name)} onClose={onClose ? () => onClose(resource) : undefined} onKeyDown={(event) => { if (onClose && event.key === "Delete") {
            event.preventDefault();
            onClose(resource);
        } }}/>)}
        </TabsList>
      </div>
      {(closable || visible.size < resources.length) && <DropdownMenu>
        <DropdownTrigger render={<Button iconOnly variant="tertiary" aria-label={labels.more}><More aria-hidden/></Button>}/>
        <DropdownContent align="end" aria-label={labels.resources} checkedIndex={resources.findIndex((resource) => resource.id === activeId)}>
          {resources.map((resource, index) => <MenuItem key={resource.id} index={index} label={resource.name} leading={leading(resource)} checked={resource.id === activeId} onSelect={() => { onSelect(resource.id); focusSelected(resource.id); }}/>)}
          {closable && <>
            <DropdownSeparator />
            <MenuItem index={resources.length} label={labels.closeOthers} disabled={resources.length < 2} onSelect={onCloseOthers}/>
            <MenuItem index={resources.length + 1} label={labels.closeAll} onSelect={onCloseAll}/>
          </>}
        </DropdownContent>
      </DropdownMenu>}
