"use client";
import { Component, lazy, Suspense, useEffect, useId, useRef, useState, type ReactNode } from "react";
import { Button } from "@ui/button";
import { Empty, EmptyHeader, EmptyTitle, EmptyDescription } from "@ui/empty";
import { FileType } from "@ui/file-type";
import { InlineNotice, InlineNoticeContent } from "@ui/inline-notice";
import { safeArtifactUrl } from "./utils";
import type { ArtifactLabels, ArtifactPanelProps, ArtifactResource, ArtifactView } from "./types";
const CodePreview = lazy(() => import("./code-preview").then((module) => ({ default: module.ArtifactCodePreview })));
function PreviewNotice({ children }: {
    children: ReactNode;
}) {
    return <div className="p-4"><InlineNotice><InlineNoticeContent>{children}</InlineNoticeContent></InlineNotice></div>;
}
function ImagePreview({ resource, labels }: {
    resource: Extract<ArtifactResource, {
        kind: "image";
    }>;
    labels: ArtifactLabels;
}) {
    const viewport = useRef<HTMLDivElement>(null);
    const [bounds, setBounds] = useState({ width: 0, height: 0 });
    const [dimensions, setDimensions] = useState({ width: 0, height: 0 });
    // Null tracks the container; numeric values are absolute image scales.
    const [zoom, setZoom] = useState<number | null>(null);
    const drag = useRef<{
        id: number;
        x: number;
        y: number;
        left: number;
        top: number;
    } | null>(null);
    const [dragging, setDragging] = useState(false);
    const hintId = useId();
    const [failed, setFailed] = useState(false);
    const [attempt, setAttempt] = useState(0);
    const url = safeArtifactUrl(resource.url);
    useEffect(() => {
        const node = viewport.current;
        if (!node)
            return;
        const measure = () => setBounds({ width: node.clientWidth, height: node.clientHeight });
        measure();
        if (typeof ResizeObserver === "undefined")
            return;
        const observer = new ResizeObserver(measure);
        observer.observe(node);
        return () => observer.disconnect();
    }, []);
    const fit = dimensions.width && bounds.width ? Math.min(Math.max(1, bounds.width - 48) / dimensions.width, Math.max(1, bounds.height - 48) / dimensions.height, 1) : 1;
    const scale = zoom ?? fit;
    const imageReady = !!url && !failed && dimensions.width > 0;
    const canPan = imageReady && (dimensions.width * scale + 48 > bounds.width || dimensions.height * scale + 48 > bounds.height);
    const resetZoom = (value: number | null) => {
        setZoom(value);
        if (viewport.current) {
            viewport.current.scrollLeft = 0;
            viewport.current.scrollTop = 0;
        }
    };
    const stopDrag = () => {
        const current = drag.current;
        drag.current = null;
        if (current && viewport.current?.hasPointerCapture?.(current.id))
            viewport.current.releasePointerCapture(current.id);
        setDragging(false);
    };
