  </div>;
}
export function ArtifactPreview({ resource, view, split, labels, renderPreview, onRetry }: {
    resource: ArtifactResource;
    view: ArtifactView;
    split: boolean;
    labels: ArtifactLabels;
    renderPreview?: ArtifactPanelProps["renderPreview"];
    onRetry?: () => void;
}) {
    if (resource.status === "loading")
        return <PreviewNotice><span role="status">{labels.loading}</span></PreviewNotice>;
    if (resource.status === "error")
        return <PreviewNotice><span role="alert">{resource.error ?? labels.failed}</span>{onRetry && <Button variant="ghost" size="sm" onClick={onRetry}>{labels.retry}</Button>}</PreviewNotice>;
    const custom = renderPreview?.(resource);
    if (custom !== undefined)
        return custom;
    if ("content" in resource)
        return <Suspense fallback={<PreviewNotice>{labels.loading}</PreviewNotice>}><CodePreview resource={resource} view={view} split={split}/></Suspense>;
    if (resource.kind === "image")
        return <ImagePreview key={resource.url} resource={resource} labels={labels}/>;
    if (resource.kind === "url")
        return <WebPreview key={resource.url} resource={resource} labels={labels}/>;
    return <div className="flex flex-1 items-center justify-center p-6"><Empty reason="no-data" scope="inline" density="compact">
    <FileType fileName={resource.name} size="xl"/>
    <EmptyHeader><EmptyTitle>{resource.name}</EmptyTitle><EmptyDescription>{labels.unsupported}</EmptyDescription></EmptyHeader>
    <p className="text-label text-fg-muted">{[resource.mimeType, resource.size !== undefined && `${resource.size.toLocaleString()} B`].filter(Boolean).join(" · ")}</p>
  </Empty></div>;
}
export class ArtifactPreviewBoundary extends Component<{
    children: ReactNode;
    labels: ArtifactLabels;
}, {
    failed: boolean;
}> {
    state = { failed: false };
    static getDerivedStateFromError() { return { failed: true }; }
    render() {
        return this.state.failed ? <PreviewNotice><span role="alert">{this.props.labels.failed}</span><Button size="sm" variant="ghost" onClick={() => this.setState({ failed: false })}>{this.props.labels.retry}</Button></PreviewNotice> : this.props.children;
    }
}

"use client";
import { ArtifactContentRenderer } from "../artifact-content-renderer";
import type { ArtifactResource, ArtifactView } from "./types";
export function ArtifactCodePreview({ resource, view, split }: {
    resource: ArtifactResource;
    view: ArtifactView;
    split: boolean;
}) {
    if (!("content" in resource))
        return null;
    if (view === "preview" && resource.kind === "markdown") {
        return <ArtifactContentRenderer mode="markdown" text={resource.content}/>;
    }
    const file = { name: resource.path ?? resource.name, contents: resource.content };
    if (view === "diff" && "previousContent" in resource && resource.previousContent !== undefined) {
        return <ArtifactContentRenderer mode="diff" oldFile={{ name: resource.kind === "code" ? resource.previousPath ?? file.name : file.name, contents: resource.previousContent }} newFile={file} diffStyle={split ? "split" : "unified"}/>;
    }
    return <ArtifactContentRenderer mode="code" file={file}/>;
}
